function save(){if(s)localStorage.setItem('desgoverno_v11_save',JSON.stringify(s));localStorage.setItem('desgoverno_v10_save',JSON.stringify(s));localStorage.setItem('desgoverno_v09_save',JSON.stringify(s));}
