function migrate(){const d=fresh();Object.keys(d).forEach(k=>{if(s[k]===undefined)s[k]=d[k]});s.archiveCount=Number.isFinite(s.archiveCount)?s.archiveCount:0;if(!Number.isFinite(s.electionAt)||s.electionAt<30)s.electionAt=s.turn+30;s.version='1.9';if(!Number.isInteger(s.selectedDistrict)||s.selectedDistrict<0||s.selectedDistrict>=(s.cityDistricts||[]).length)s.selectedDistrict=0;delete s.stateRevolt;delete s.stateExtinguished;if(!Array.isArray(s.cityDistricts))s.cityDistricts=d.cityDistricts;if(!Array.isArray(s.crisisFlags))s.crisisFlags=[];}
function createMinister(m,i){return {name:m[2],role:m[0],emoji:m[1],trait:m[3],loyalty:60+i*5,mood:['ambicioso','pragmático','temperamental','vaidoso','calculista'][i%5],agenda:['quer controlar o orçamento','exige mais recursos','busca protagonismo','protege seus aliados','quer ampliar sua influência'][i%5],lastAction:''};}
function normalizeMinisters(){if(!Array.isArray(s.ministers))s.ministers=[];s.ministers=s.ministers.filter(Boolean).slice(0,MAX_MINISTERS);const used=new Set();s.ministers=s.ministers.filter(m=>{if(!m.role||used.has(m.role))return false;used.add(m.role);return true;});while(s.ministers.length<MAX_MINISTERS){const next=ministerPool.find(m=>!used.has(m[0]));if(!next)break;used.add(next[0]);s.ministers.push(createMinister(next,s.ministers.length));}}
function start(existing=false){s=existing?load():fresh();if(!s)return;migrate();normalizeMinisters();if(!s.news)s.news=[];if(!s.defeated)s.defeated=[false,false,false,false];s.ended=false;s.gameOver=false;s.won=false;$('startScreen').classList.add('hidden');$('game').classList.remove('hidden');addNews('GOVERNO EM POSSE',`${s.name} assume a condução de Barzi. Especialistas recomendam cautela; o gabinete recomenda aplausos.`);render();newEvent();drawScene();if(timer)clearInterval(timer);timer=setInterval(tick,1000);}
