 if(approved){s.ended=true;s.ending='impeachment';showEnd('IMPEACHMENT APROVADO','A terceira tentativa de comprar o silêncio dos investigadores provocou uma votação no Congresso. O impeachment foi aprovado e seu governo terminou.');}
